var t={about:{title:"За картава",hiking:"<p>На картава се покажани означени пешачки патеки ширум светот.</p>\n",cycling:"<p>На картава се покажани означени велосипедски патеки ширум светот.</p>\n",mtb:"<p>На картава се покажани означени патеки за планински велосипедизам ширум светот.</p>\n",skating:"<p>На картава се покажани означени патеки за ролерки ширум светот.</p>\n"},rendering:{title:"Испис на податоци од OSM"},hierarchies:{title:"Односни хиерархии"},osmc:{title:"Ознаката osmc:symbol"},hikinglocal:{title:"Регионален испис",text:"<p>Во светот постојат многу различни начини на означување на планинарски патеки. Иако на картата настојуваме да ги користиме најопштите ознаки за да се прикажат добро, системот не може да работи за сите системи, особено кај мрежи од патеки. За да се вклучат и овие ситеми, картата може да се прилагоди за региони кајшто стандарниот испис е недоволен.</p>\n<p>Подолу е наведен список на региони што користат посебни картографски симболи. На крајот од страницата има совети за тоа како да наместите вашиот регион да се испише на посебен начин.</p>\n"},elevationprofiles:{title:"Висински профили"},technical:{title:"Технички поединости"},legal:{title:"Услови на употреба"},acknowledgements:{title:"Благодарности"},contact:{title:"Контакт"}},e=t.about,i=t.rendering,l=t.hierarchies,n=t.osmc,a=t.hikinglocal,c=t.elevationprofiles,o=t.technical,p=t.legal,r=t.acknowledgements,s=t.contact;export{e as about,r as acknowledgements,s as contact,t as default,c as elevationprofiles,l as hierarchies,a as hikinglocal,p as legal,n as osmc,i as rendering,o as technical};
